import os
from typing import Any, Dict, List, Optional

import requests


def extract_table_cells_and_rows(document_url: str, api_key: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Google Cloud Document AI.

    Expected output format:
    {
        "tables": [
            {
                "page": 1,
                "row_count": 3,
                "column_count": 4,
                "rows": [
                    [
                        {"text": "...", "row_span": 1, "col_span": 1, "start": 0.12, "end": 0.15},
                        ...
                    ],
                    ...
                ]
            }
        ]
    }
    """
    api_key = api_key or os.getenv("GOOGLE_CLOUD_DOCUMENT_AI_API_KEY")
    if not api_key:
        raise ValueError("Missing Google Cloud Document AI API key")

    processor_name = os.getenv("GOOGLE_CLOUD_DOCUMENT_AI_PROCESSOR_NAME")
    if not processor_name:
        raise ValueError(
            "Missing Google Cloud Document AI processor name in GOOGLE_CLOUD_DOCUMENT_AI_PROCESSOR_NAME"
        )

    endpoint = (
        f"https://documentai.googleapis.com/v1/{processor_name}:process"
    )

    payload = {
        "inlineDocument": None,
        "rawDocument": {
            "mimeType": "application/pdf",
            "uri": document_url,
        },
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    resp = requests.post(endpoint, headers=headers, json=payload, timeout=120)
    resp.raise_for_status()
    data = resp.json()

    document = data.get("document", {})
    text = document.get("text", "")
    pages = document.get("pages", [])

    def get_text(anchor: Dict[str, Any]) -> str:
        if not anchor:
            return ""
        fragments = []
        for seg in anchor.get("textSegments", []):
            start = int(seg.get("startIndex", 0) or 0)
            end = int(seg.get("endIndex", 0) or 0)
            if end > start:
                fragments.append(text[start:end])
        return "".join(fragments).strip()

    tables_out: List[Dict[str, Any]] = []

    for page_index, page in enumerate(pages):
        for table in page.get("tables", []):
            rows_out: List[List[Dict[str, Any]]] = []
            cells = table.get("bodyRows", []) + table.get("headerRows", [])
            for row in cells:
                row_cells: List[Dict[str, Any]] = []
                for cell in row.get("cells", []):
                    row_cells.append(
                        {
                            "text": get_text(cell.get("layout", {}).get("textAnchor", {})),
                            "row_span": int(cell.get("rowSpan", 1) or 1),
                            "col_span": int(cell.get("colSpan", 1) or 1),
                            "bounding_poly": cell.get("layout", {}).get("boundingPoly", {}),
                        }
                    )
                rows_out.append(row_cells)

            tables_out.append(
                {
                    "page": page_index + 1,
                    "row_count": len(rows_out),
                    "column_count": max((len(r) for r in rows_out), default=0),
                    "rows": rows_out,
                }
            )

    return {"tables": tables_out}
